 46→func runAttach(ctx context.Context, w io.Writer, sessionID string) error {
 47→	logCtx := logging.WithComponent(ctx, "attach")
 48→
 49→	// Validate session ID format
 50→	if err := validation.ValidateSessionID(sessionID); err != nil {
 51→		return fmt.Errorf("invalid session ID: %w", err)
 52→	}
 53→
 54→	// Ensure we're in a git repo
 55→	repoRoot, err := paths.WorktreeRoot(ctx)
 56→	if err != nil {
 57→		return fmt.Errorf("not a git repository: %w", err)
 58→	}
 59→
 60→	// Check session isn't already tracked
 61→	store, err := session.NewStateStore(ctx)
 62→	if err != nil {
 63→		return fmt.Errorf("failed to open session store: %w", err)
 64→	}
 65→	existing, err := store.Load(ctx, sessionID)
 66→	if err != nil {
 67→		return fmt.Errorf("failed to check existing session: %w", err)
 68→	}
 69→	if existing != nil {
 70→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 71→	}
 72→
 73→	// Resolve Claude Code agent and transcript path
 74→	ag, err := agent.Get(agent.AgentNameClaudeCode)
 75→	if err != nil {
 76→		return fmt.Errorf("claude code agent not available: %w", err)
 77→	}
 78→
 79→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
 80→	if err != nil {
 81→		return fmt.Errorf("failed to resolve transcript path: %w", err)
 82→	}
 83→	if _, statErr := os.Stat(transcriptPath); os.IsNotExist(statErr) {
 84→		return fmt.Errorf("transcript not found at %s\nIs the session ID correct?", transcriptPath)
 85→	}
 86→
 87→	// Read transcript data
 88→	transcriptData, err := ag.ReadTranscript(transcriptPath)
 89→	if err != nil {
 90→		return fmt.Errorf("failed to read transcript: %w", err)
 91→	}
 92→
 93→	// Extract modified files from transcript
 94→	var modifiedFiles []string
 95→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
 96→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
 97→			logging.Warn(logCtx, "failed to extract modified files from transcript")
 98→		} else {
 99→			modifiedFiles = files
100→		}
101→	}
102→
103→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
104→	changes, err := DetectFileChanges(ctx, nil)
105→	if err != nil {
106→		logging.Warn(logCtx, "failed to detect file changes")
107→	}
108→
109→	// Filter and normalize paths
110→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
111→	var relNewFiles, relDeletedFiles []string
112→	if changes != nil {
113→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
114→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
115→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
116→	}
117→
118→	// Filter to uncommitted files only
119→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
120→
121→	// Ensure strategy setup
122→	if err := strategy.EnsureSetup(ctx); err != nil {
123→		logging.Warn(logCtx, "failed to ensure strategy setup")
124→	}
125→
126→	// Create session metadata directory and copy transcript
127→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
128→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
129→	if err != nil {
130→		sessionDirAbs = sessionDir
131→	}
132→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
133→		return fmt.Errorf("failed to create session directory: %w", err)
134→	}
135→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
136→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
137→		return fmt.Errorf("failed to write transcript: %w", err)
138→	}
139→
140→	// Get git author
141→	author, err := GetGitAuthor(ctx)
142→	if err != nil {
143→		return fmt.Errorf("failed to get git author: %w", err)
144→	}
145→
146→	// Extract first prompt from transcript for the commit message
147→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
148→	commitMessage := generateCommitMessage(firstPrompt, agent.AgentTypeClaudeCode)
149→
150→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
151→	strat := GetStrategy(ctx)
152→	if err := strat.InitializeSession(ctx, sessionID, agent.AgentTypeClaudeCode, transcriptPath, firstPrompt, ""); err != nil {
153→		return fmt.Errorf("failed to initialize session: %w", err)
154→	}
155→
156→	// Update the session state with attach-specific metadata
157→	state, err := strategy.LoadSessionState(ctx, sessionID)
158→	if err != nil {
159→		return fmt.Errorf("failed to load session state: %w", err)
160→	}
161→	if state != nil {
162→		state.CLIVersion = versioninfo.Version
163→		state.TranscriptPath = transcriptPath
164→		if err := strategy.SaveSessionState(ctx, state); err != nil {
165→			return fmt.Errorf("failed to save session state: %w", err)
166→		}
167→	}
168→
169→	// Build step context and save checkpoint
170→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
171→
172→	stepCtx := strategy.StepContext{
173→		SessionID:      sessionID,
174→		ModifiedFiles:  relModifiedFiles,
175→		NewFiles:       relNewFiles,
176→		DeletedFiles:   relDeletedFiles,
177→		MetadataDir:    sessionDir,
178→		MetadataDirAbs: sessionDirAbs,
179→		CommitMessage:  commitMessage,
180→		TranscriptPath: transcriptPath,
181→		AuthorName:     author.Name,
182→		AuthorEmail:    author.Email,
183→		AgentType:      agent.AgentTypeClaudeCode,
184→	}
185→
186→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
187→		return fmt.Errorf("failed to save checkpoint: %w", err)
188→	}
189→
190→	// Condense session to permanent storage and generate checkpoint ID
191→	var checkpointIDStr string
192→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
193→		logging.Warn(logCtx, "failed to condense session — checkpoint saved on shadow branch only")
194→	} else {
195→		// Read the checkpoint ID from the updated session state
196→		if condensedState, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr == nil && condensedState != nil {
197→			checkpointIDStr = condensedState.LastCheckpointID.String()
198→		}
199→	}
200→
201→	// Transition to IDLE (attach is a completed turn)
202→	if finalState, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr == nil && finalState != nil {
203→		now := time.Now()
204→		finalState.LastInteractionTime = &now
205→		if transErr := strategy.TransitionAndLog(ctx, finalState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
206→			logging.Warn(logCtx, "failed to transition session to idle")
207→		}
208→		if saveErr := strategy.SaveSessionState(ctx, finalState); saveErr != nil {
209→			logging.Warn(logCtx, "failed to save session state after transition")
210→		}
211→	}
212→
213→	// Print confirmation
214→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
215→	if totalChanges > 0 {
216→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
217→	} else {
218→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
219→	}
220→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
221→
222→	// Print checkpoint trailer for user to copy into commit message
223→	if checkpointIDStr != "" {
224→		fmt.Fprintf(w, "\nEntire-Checkpoint: %s\n", checkpointIDStr)
225→	}
226→
227→	return nil
228→}
